// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {TimelockController} from "../src/TimelockController.sol";

contract InvMutTest is Test {
    TimelockController c;

    function setUp() public {
        c = new TimelockController(0, new address[](0), new address[](0));
    }

    function testFuzz_property(bytes32 role) public {
        bytes32 timelockAdmin = keccak256("TIMELOCK_ADMIN_ROLE");
        bytes32 proposer = keccak256("PROPOSER_ROLE");
        bytes32 executor = keccak256("EXECUTOR_ROLE");
        vm.assume(role != 0 && role != timelockAdmin && role != proposer && role != executor);
        // For any such role, the stored adminRole is bytes32(0), so the queried
        // admin must differ from the queried role itself.
        assertTrue(c.getRoleAdmin(role) != role);
    }
}
